信号量定义：
semaphore empty = 1;  // 盘子是否为空(同步信号量)
semaphore apple = 0;  // 盘子中是否有苹果
semaphore orange = 0; // 盘子中是否有橘子
semaphore mutex = 1;  // 互斥信号量，保护对盘子的操作

父亲进程：
while(true) {
    生产苹果;
    P(empty);        // 等待盘子为空
    P(mutex);        // 互斥访问盘子
    放入苹果;
    V(mutex);
    V(apple);        // 通知儿子有苹果了
}

母亲进程：
while(true) {
    生产橘子;
    P(empty);        // 等待盘子为空
    P(mutex);
    放入橘子;
    V(mutex);
    V(orange);       // 通知女儿有橘子了
}

儿子进程：
while(true) {
    P(apple);        // 等待苹果
    P(mutex);
    取走苹果;
    V(mutex);
    V(empty);        // 通知盘子空了
    吃苹果;
}

女儿进程：
while(true) {
    P(orange);       // 等待橘子
    P(mutex);
    取走橘子;
    V(mutex);
    V(empty);        // 通知盘子空了
    吃橘子;
}

注意：P(empty) 和 P(mutex) 的顺序必须正确，先P(同步信号量)再P(互斥信号量)，否则可能死锁。

信号量定义：
semaphore mutex = 1;        // 互斥访问货架
semaphore empty = N;        // 货架空位数
semaphore A_count = 0;      // 货架上A零件的数量
semaphore B_count = 0;      // 货架上B零件的数量

车间A：                       车间B：
while(true) {                 while(true) {
    生产A零件;                    生产B零件;
    P(empty);                     P(empty);
    P(mutex);                     P(mutex);
    将A零件放入货架;              将B零件放入货架;
    V(mutex);                     V(mutex);
    V(A_count);                   V(B_count);
}                             }

装配车间：
while(true) {
    P(A_count);     // 等待至少1个A
    P(B_count);     // 等待至少1个B
    P(mutex);       // 互斥取零件
    取走1个A零件和1个B零件;
    V(mutex);
    V(empty);       // 释放2个空位
    V(empty);       // 拿走了2个物品，产生2个空位
    装配;
}

关键点：装配车间需要同时取A和B，所以先P(A_count)再P(B_count)确保两种零件都有。取走两个零件，需要两次V(empty)归还货架空位。

信号量定义：
semaphore rw_mutex = 1;  // 读写互斥，保护数据区
semaphore mutex = 1;     // 互斥访问readcount
int readcount = 0;       // 当前在读的读者数

读者代码：
void reader() {
    while(true) {
        P(mutex);
        readcount++;
        if (readcount == 1)  // 第一个读者
            P(rw_mutex);     // 锁住数据区，阻止写者
        V(mutex);

        读数据...

        P(mutex);
        readcount--;
        if (readcount == 0)  // 最后一个读者离开
            V(rw_mutex);     // 释放数据区
        V(mutex);
    }
}

写者代码：
void writer() {
    while(true) {
        P(rw_mutex);    // 独占访问
        写数据...
        V(rw_mutex);    // 释放
    }
}

写者饥饿原因：只要有一个读者在读(readcount>0)，rw_mutex就被占用，写者被阻塞。如果持续有新读者到来(readcount维持在>=1)，写者永远无法获取rw_mutex——这就是读者优先带来的写者饥饿问题。

信号量定义：
semaphore rw_mutex = 1;    // 保护数据区(读/写互斥)
semaphore mutex1 = 1;       // 保护readcount
semaphore mutex2 = 1;       // 保护writecount
semaphore w_mutex = 1;      // 实现写者优先的关键信号量
int readcount = 0;          // 读者计数
int writecount = 0;         // 写者计数

读者代码：
void reader() {
    while(true) {
        P(w_mutex);          // 在w_mutex上排队
        P(mutex1);
        readcount++;
        if (readcount == 1)
            P(rw_mutex);    // 第一个读者锁数据区
        V(mutex1);
        V(w_mutex);          // 释放w_mutex，允许后续排队

        读数据...

        P(mutex1);
        readcount--;
        if (readcount == 0)
            V(rw_mutex);
        V(mutex1);
    }
}

写者代码：
void writer() {
    while(true) {
        P(mutex2);
        writecount++;
        if (writecount == 1)
            P(w_mutex);      // 第一个写者抢占w_mutex
        V(mutex2);

        P(rw_mutex);         // 获取数据区独占权
        写数据...
        V(rw_mutex);

        P(mutex2);
        writecount--;
        if (writecount == 0)
            V(w_mutex);      // 最后一个写者释放w_mutex
        V(mutex2);
    }
}

关键机制：当有写者到来时(writecount>=1)，w_mutex被占用，后续读者被阻在w_mutex的P操作上。只有当所有写者完成后(writecount=0)才V(w_mutex)放行读者。

信号量定义：
semaphore rw_mutex = 1;   // 保护数据区
semaphore mutex = 1;       // 保护readcount
semaphore queue = 1;       // 排队信号量(公平竞争的关键)
int readcount = 0;

读者代码：
void reader() {
    while(true) {
        P(queue);          // 所有进程在此排队
        P(mutex);
        readcount++;
        if (readcount == 1)
            P(rw_mutex);   // 第一个读者锁住数据区
        V(mutex);
        V(queue);          // 释放queue让下一个进程排队

        读数据...

        P(mutex);
        readcount--;
        if (readcount == 0)
            V(rw_mutex);
        V(mutex);
    }
}

写者代码：
void writer() {
    while(true) {
        P(queue);          // 所有进程在此排队
        P(rw_mutex);       // 获取独占权
        V(queue);          // 释放queue

        写数据...

        V(rw_mutex);
    }
}

原理：queue信号量使得所有读者和写者按到达顺序排队。当一个进程获得queue后，只有持有它可以继续(读者进入读区、写者进入写区)，然后释放queue供下一个进程排队。这样就保证了FIFO顺序，不会产生饥饿。

方法一：限制最多4位哲学家同时拿起筷子(使用计数信号量)
semaphore chopstick[5] = {1,1,1,1,1};  // 5根筷子
semaphore limit = 4;  // 限制最多4人同时尝试拿筷子

哲学家i(i=0,1,2,3,4)：
void philosopher(int i) {
    while(true) {
        思考...
        P(limit);          // 限制拿筷子人数
        P(chopstick[i]);   // 拿左筷子
        P(chopstick[(i+1)%5]); // 拿右筷子
        进餐...
        V(chopstick[i]);   // 放左筷子
        V(chopstick[(i+1)%5]); // 放右筷子
        V(limit);
    }
}

方法二：奇数先左后右，偶数先右后左(破坏循环等待)
该方案不需要额外信号量，只需改变拿筷子顺序。

方法三：同时拿两根筷子(AND型信号量)
SP(chopstick[i], chopstick[(i+1)%5]);
进餐;
SV(chopstick[i], chopstick[(i+1)%5]);

三种方案都能避免死锁，方法一实现最简单、性能好。

信号量定义：
semaphore chopstick[5] = {1,1,1,1,1};

哲学家i代码：
void philosopher(int i) {
    while(true) {
        思考...
        // AND型P操作——同时申请左筷子和右筷子
        SP(chopstick[i], chopstick[(i+1)%5]);
        进餐...
        // AND型V操作——同时释放两根筷子
        SV(chopstick[i], chopstick[(i+1)%5]);
    }
}

SP操作的实现原理(伪代码)：
void SP(semaphore S1, semaphore S2) {
    while(true) {
        if (S1.value >= 1 && S2.value >= 1) {
            S1.value--; S2.value--;
            break;
        } else {
            // 将进程加入S1和S2的等待队列
            block();
        }
    }
}

关键：SP操作原子性地检查和分配多个资源，要么全部分配成功，要么一个也不分配(进程阻塞)。这样就避免了部分分配导致的死锁。

信号量定义：
semaphore customers = 0;    // 等待理发的顾客数(用于叫醒理发师)
semaphore barber = 0;       // 理发师是否就绪
semaphore mutex = 1;        // 互斥访问waiting变量
int waiting = 0;            // 当前在等候椅上的顾客数
const int N = ...;          // 等候椅数量

理发师代码：
void barber() {
    while(true) {
        P(customers);       // 等待顾客(无顾客时睡觉)
        P(mutex);
        waiting--;          // 一位顾客从等候椅起身理发
        V(barber);          // 通知该顾客可以理发
        V(mutex);
        理发...
    }
}

顾客代码：
void customer() {
    P(mutex);
    if (waiting < N) {     // 有空椅子
        waiting++;
        V(customers);       // 通知理发师有顾客
        V(mutex);
        P(barber);          // 等待理发师叫自己
        被理发...
    } else {               // 没有空椅子
        V(mutex);
        离开;               // 不等待，直接离开
    }
}

分析：customers信号量记录等候的顾客数(含正在理发的)。理发师通过P(customers)在没有顾客时睡眠。顾客到来时V(customers)唤醒理发师。barber信号量用于同步"理发师叫顾客起身"和"顾客从等候椅起身去理发椅"这两个动作。

