semaphore offer1 = 0;   // 烟草+纸可用(给需要火柴的吸烟者)
semaphore offer2 = 0;   // 烟草+火柴可用(给需要纸的吸烟者)
semaphore offer3 = 0;   // 纸+火柴可用(给需要烟草的吸烟者)
semaphore finish = 0;   // 吸烟者完成，通知供应商
semaphore mutex = 1;     // 互斥??? 供应商只有一个，无需
int turn;                // 记录本轮提供的是哪种组合(用随机数)

供应商代码：
void provider() {
    while(true) {
        turn = random() % 3;  // 随机选择0,1,2
        switch(turn) {
            case 0: V(offer1); break;  // 提供烟草+纸
            case 1: V(offer2); break;  // 提供烟草+火柴
            case 2: V(offer3); break;  // 提供纸+火柴
        }
        P(finish);  // 等待吸烟者完成
    }
}

吸烟者1(有火柴，需要烟草+纸)：
while(true) { P(offer1); 吸烟; V(finish); }

吸烟者2(有纸，需要烟草+火柴)：
while(true) { P(offer2); 吸烟; V(finish); }

吸烟者3(有烟草，需要纸+火柴)：
while(true) { P(offer3); 吸烟; V(finish); }

关键理解：三个offer信号量分别代表三种材料组合。供应商V对应offer，对应的吸烟者被唤醒。finish确保供应商等吸烟者完成后再提供下一组材料。

信号量定义：
semaphore bridge = 1;  // 互斥使用桥

左端过桥者：                   右端过桥者：
void left_pass() {             void right_pass() {
    P(bridge);                     P(bridge);
    过桥...                        过桥...
    V(bridge);                     V(bridge);
}                             }

分析：这是最简单的互斥问题，用单一互斥信号量即可。两端的人公平竞争bridge信号量，按FIFO顺序获得桥的使用权。

信号量定义：
semaphore bridge = 1;       // 桥的使用权
semaphore mutexL = 1;       // 保护左方向计数
semaphore mutexR = 1;       // 保护右方向计数
semaphore queue = 1;        // 公平排队
int countL = 0, countR = 0; // 当前桥上左右方向的人数

左方向过桥者：
void left_pass() {
    P(queue);               // 排队
    P(mutexL);
    countL++;
    if (countL == 1)        // 第一个左向的人
        P(bridge);          // 抢占桥
    V(mutexL);
    V(queue);               // 释放queue

    过桥...

    P(mutexL);
    countL--;
    if (countL == 0)        // 最后一个左向的人离开
        V(bridge);          // 释放桥
    V(mutexL);
}

右方向过桥者(对称代码)：
void right_pass() {
    P(queue);
    P(mutexR);
    countR++;
    if (countR == 1)
        P(bridge);
    V(mutexR);
    V(queue);

    过桥...

    P(mutexR);
    countR--;
    if (countR == 0)
        V(bridge);
    V(mutexR);
}

关键：这个方案与读者-写者问题高度相似——同方向可并发通过(类似读者可并发读)，不同方向互斥(类似读-写互斥)。queue信号量保证公平性。

信号量定义：
semaphore empty1 = 1;  // buf空闲
semaphore full1 = 0;   // buf有数据
semaphore empty2 = 1;  // buf2空闲
semaphore full2 = 0;   // buf2有数据

P1(输入进程)：                  P2(加工进程)：
while(true) {                   while(true) {
    读数据到data;                   P(full1);
    P(empty1);                     从buf取数据到data;
    buf = data;                    V(empty1);
    V(full1);                      加工data;
}                                 P(empty2);
                                  buf2 = 加工后的数据;
P3(输出进程)：                      V(full2);
while(true) {                   }
    P(full2);
    从buf2取数据;
    V(empty2);
    输出数据;
}

这是典型的生产者-消费者流水线，每个进程既是一个阶段的消费者也是下一个阶段的生产者。empty/full信号量对保证了相邻阶段之间的同步。

信号量定义：
semaphore mutex = 1;     // 路口使用权
semaphore mutexEW = 1;   // 保护东西方向计数
semaphore mutexSN = 1;   // 保护南北方向计数
int countEW = 0;         // 东西方向正在通过的车辆数
int countSN = 0;         // 南北方向正在通过的车辆数

东西方向车辆：
void EW_car() {
    P(mutexEW);
    countEW++;
    if (countEW == 1)    // 第一辆东西车
        P(mutex);        // 占用路口
    V(mutexEW);

    通过路口...

    P(mutexEW);
    countEW--;
    if (countEW == 0)    // 最后一辆东西车离开
        V(mutex);        // 释放路口
    V(mutexEW);
}

南北方向车辆(对称代码)：
void SN_car() {
    P(mutexSN);
    countSN++;
    if (countSN == 1)
        P(mutex);
    V(mutexSN);

    通过路口...

    P(mutexSN);
    countSN--;
    if (countSN == 0)
        V(mutex);
    V(mutexSN);
}

这个方案允许同一方向多辆车同时通过路口(同向不冲突)，但不同方向必须互斥。类似读者-写者问题中多读者同时读的场景。

信号量定义：
semaphore cashiers = M;   // 可用收银台数量(=M)
semaphore mutex = 1;       // 互斥访问队列(如果使用显式队列)

顾客进程：
void customer() {
    P(cashiers);     // 申请收银台(如果无空闲则排队等待)
    接受收银服务...   // 每个顾客服务时长不同
    V(cashiers);     // 释放收银台
}

收银员进程：
void cashier(int id) {
    while(true) {
        等待顾客...     // 收银员可以被P(cashiers)唤醒
        为顾客服务...
    }
}

实际上收银员不需要主动调用PV操作——他们只是被动的服务提供者。这里的模型是：顾客竞争收银台资源(信号量cashiers初值为M)。当M>0时有空位，顾客P(cashiers)直接通过；M=0时顾客阻塞等待。顾客完成结账后V(cashiers)释放一个收银台。

信号量定义：
semaphore mutex = 1;     // 互斥访问计数器
semaphore O_queue = 0;   // O线程等待
semaphore H_queue = 0;   // H线程等待
int H_count = 0;         // 当前已到达的H原子数

H线程：
void H_thread() {
    P(mutex);
    H_count++;
    if (H_count >= 2) {
        // 有足够的H原子了，检查是否有O等待
        V(H_queue);     // 唤醒一个H
        V(H_queue);     // 唤醒另一个H
        H_count -= 2;
        V(O_queue);     // 唤醒O(生成水分子)
        V(mutex);
    } else {
        V(mutex);
        P(H_queue);     // 等待O或者其他H
    }
    生成水分子(这一步在唤醒后执行);
}

O线程：
void O_thread() {
    P(mutex);
    if (H_count >= 2) {
        // 已有两个H在等
        V(H_queue);     // 唤醒第一个H
        V(H_queue);     // 唤醒第二个H
        H_count -= 2;
        V(mutex);
    } else {
        V(mutex);
        P(O_queue);     // 等待H到达
        P(mutex);       // 被唤醒后不需要再操作，直接V
        V(mutex);
    }
    生成水分子;
}

说明：这个方案使用计数+信号量的方式，O线程和H线程到达后检查是否满足生成水分子的条件(1O+2H)，满足则唤醒所有相关线程，不满足则阻塞等待。

信号量定义：
semaphore S_em;  // emQ中空缓冲的数量(初值为总缓冲数)
semaphore S_in;  // inQ中满输入缓冲的数量(初值0)
semaphore S_out; // outQ中满输出缓冲的数量(初值0)
semaphore mutex_em, mutex_in, mutex_out; //分别保护三个队列

(1) 收容输入(设备→输入缓冲)：
// 将设备数据装入一个空缓冲
Buf* GetBuf_Input() {
    P(S_em);          // 等待有空闲缓冲
    P(mutex_em);
    Buf* b = 从emQ取出一个空缓冲;
    V(mutex_em);
    // 将设备输入数据填入b(由设备驱动完成)
    return b;
}
将填满的b放入inQ:
void PutToInQ(Buf* b) {
    P(mutex_in);
    将b加入inQ队尾;
    V(mutex_in);
    V(S_in);          // 通知"有满的输入数据"
}

(2) 提取输入(进程读数据)：
Buf* GetBuf_Read() {
    P(S_in);          // 等待有满的输入缓冲
    P(mutex_in);
    Buf* b = 从inQ取出第一个满缓冲;
    V(mutex_in);
    return b;         // 进程读取b中的数据
}
读完数据后归还:
void ReturnToEmQ(Buf* b) {
    P(mutex_em);
    将b加入emQ队尾;
    V(mutex_em);
    V(S_em);          // 空缓冲+1
}

(3) 收容输出(进程输出数据)：
Buf* GetBuf_Output() {
    P(S_em);          // 等待空缓冲
    P(mutex_em);
    Buf* b = 从emQ取出空缓冲;
    V(mutex_em);
    // 进程将要输出的数据写入b
    return b;
}
将满的输出缓冲放入outQ:
void PutToOutQ(Buf* b) {
    P(mutex_out);
    将b加入outQ队尾;
    V(mutex_out);
    V(S_out);         // 通知"有满的输出数据"
}

(4) 提取输出(outQ→设备输出)：
Buf* GetBuf_Write() {
    P(S_out);         // 等待有满的输出缓冲
    P(mutex_out);
    Buf* b = 从outQ取出满缓冲;
    V(mutex_out);
    // 设备驱动将b中的数据输出到设备
    return b;
}
输出完成后归还:
void ReturnBuf(Buf* b) {
    P(mutex_em);
    将b加入emQ;
    V(mutex_em);
    V(S_em);
}

这四种操作构成了完整的I/O缓冲池生命周期：空缓冲→(收容输入)→输入缓冲→(提取输入)→空缓冲；或空缓冲→(收容输出)→输出缓冲→(提取输出)→空缓冲。每个队列用一个信号量控制生产者-消费者同步，用互斥信号量保护队列数据结构。
